oxy_webhelp_navlinks = {"manage_agent_operations_policies-d39536e63471":{"topics":[{"title":"How policies work","shortdesc":"<p class=\"shortdesc\">A policy is a named rule with a severity that <span class=\"ph\">Agent Cloud<\/span> evaluates against         your agents, tools, and sessions. When agent activity breaks a policy, <span class=\"ph\">Agent Cloud<\/span> records a violation or an alert and, depending on the policy's         enforcement mode, can stop the action.<\/p>","href":"agent_cloud\/how_policies_work_agent_cloud_all.html","attributes":{"data-id":"how_policies_work_agent_cloud"},"menu":{"hasChildren":false},"tocID":"how_policies_work_agent_cloud-d39536e63484","next":"how_policies_work_agent_cloud-d39536e63484"},{"title":"Enforcement modes","shortdesc":"<p class=\"shortdesc\">The enforcement mode of a policy determines what happens when agent activity breaks         it: Monitor records an alert, Block stops the action before it runs, and Ask hands the         action to the approval prompt of the agent.<\/p>","href":"agent_cloud\/enforcement_modes_agent_cloud_all.html","attributes":{"data-id":"policy_enforcement_types_agent_cloud"},"menu":{"hasChildren":false},"tocID":"policy_enforcement_types_agent_cloud-d39536e63535","next":"policy_enforcement_types_agent_cloud-d39536e63535"},{"title":"Blocking support by connection","shortdesc":"<p class=\"shortdesc\">Which items <span class=\"ph\">Agent Cloud<\/span> can block, and whether Ask is supported, depends on         the connection. Check this table before you set a policy to Block.<\/p>","href":"agent_cloud\/tool_blocking_support.html","attributes":{"data-id":"tool_blocking_support"},"menu":{"hasChildren":false},"tocID":"tool_blocking_support-d39536e63557","topics":[]},{"title":"<span class=\"ph\">Agent Cloud<\/span> system policies","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> includes multiple system policies. These policies are not         enabled by default. You can enable them from the Policies page.<\/p>","href":"agent_cloud\/agent_cloud_system_policies.html","attributes":{"data-id":"agent_cloud_system_policies"},"menu":{"hasChildren":false},"tocID":"agent_cloud_system_policies-d39536e63571","topics":[]},{"title":"<span class=\"ph\">Agent Cloud<\/span> policy packs","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> policy packs are curated collections of system policies you         can add to your <span class=\"ph\">Agent Cloud<\/span> account to enable a focused set of controls for a         specific risk area, compliance framework, or industry.<\/p>","href":"agent_cloud\/policy_packs_agent_cloud_all.html","attributes":{"data-id":"policy_packs_agent_cloud"},"menu":{"hasChildren":false},"tocID":"policy_packs_agent_cloud-d39536e63586","next":"policy_packs_agent_cloud-d39536e63586"},{"title":"Custom policies","shortdesc":"<p class=\"shortdesc\">A custom policy is a rule that you write in plain English. The Semantic AI Governance         Engine turns it into a policy that it judges against agent activity by intent, not by         matching keywords.<\/p>","href":"agent_cloud\/custom_policies.html","attributes":{"data-id":"custom_policies"},"menu":{"hasChildren":false},"tocID":"custom_policies-d39536e63657","next":"custom_policies-d39536e63657"},{"title":"Alerts and violations","shortdesc":"<p class=\"shortdesc\">Alerts and violations are the findings that your policies produce. An alert is a         specific action or message that broke a policy. A violation is a standing configuration that         breaks one.<\/p>","href":"agent_cloud\/alerts_violations_agent_cloud_all.html","attributes":{"data-id":"alerts_violations_agent_cloud"},"menu":{"hasChildren":false},"tocID":"alerts_violations_agent_cloud-d39536e63718","next":"alerts_violations_agent_cloud-d39536e63718"},{"title":"Viewing insights","shortdesc":"<p class=\"shortdesc\">View the Insights page to review security recommendations and posture         improvements identified by <span class=\"ph\">Agent Cloud<\/span>.<\/p>","href":"agent_cloud\/viewing_insights.html","attributes":{"data-id":"viewing_insights"},"menu":{"hasChildren":false},"tocID":"viewing_insights-d39536e63762","topics":[]}]}};